#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "mapper_expr.h"

typedef union _mapper_signal_value_t
{
    float f;
    int i32;
} mapper_signal_value_t;

#define STACK_SIZE 256

static float minf(float x, float y) { if (y < x) return y; else return x; }
static float maxf(float x, float y) { if (y > x) return y; else return x; }
static float pif() { return M_PI; }

typedef enum {
    FUNC_UNKNOWN=-1, FUNC_POW=0, FUNC_SIN, FUNC_COS, FUNC_TAN, FUNC_ABS,
    FUNC_SQRT, FUNC_LOG, FUNC_LOG10, FUNC_EXP, FUNC_FLOOR, FUNC_ROUND,
    FUNC_CEIL, FUNC_ASIN, FUNC_ACOS, FUNC_ATAN, FUNC_ATAN2, FUNC_SINH,
    FUNC_COSH, FUNC_TANH, FUNC_LOGB, FUNC_EXP2, FUNC_LOG2, FUNC_HYPOT,
    FUNC_CBRT, FUNC_TRUNC, FUNC_MIN, FUNC_MAX, FUNC_PI, N_FUNCS
} expr_func_t;

static struct { const char *name; unsigned int arity; void *func; } function_table[] = {
    { "pow", 2, powf }, { "sin", 1, sinf }, { "cos", 1, cosf }, { "tan", 1, tanf },
    { "abs", 1, fabsf }, { "sqrt", 1, sqrtf }, { "log", 1, logf }, { "log10", 1, log10f },
    { "exp", 1, expf }, { "floor", 1, floorf }, { "round", 1, roundf }, { "ceil", 1, ceilf },
    { "asin", 1, asinf }, { "acos", 1, acosf }, { "atan", 1, atanf }, { "atan2", 2, atan2f },
    { "sinh", 1, sinhf }, { "cosh", 1, coshf }, { "tanh", 1, tanhf }, { "logb", 1, logbf },
    { "exp2", 1, exp2f }, { "log2", 1, log2f }, { "hypot", 2, hypotf }, { "cbrt", 1, cbrtf },
    { "trunc", 1, truncf }, { "min", 2, minf }, { "max", 2, maxf }, { "pi", 0, pif },
};

typedef struct _token {
    enum { TOK_FLOAT, TOK_INT, TOK_OP, TOK_OPEN_PAREN, TOK_CLOSE_PAREN, TOK_VAR,
           TOK_OPEN_SQUARE, TOK_CLOSE_SQUARE, TOK_OPEN_CURLY, TOK_CLOSE_CURLY,
           TOK_FUNC, TOK_COMMA, TOK_END, TOK_TOFLOAT, TOK_TOINT32 } type;
    union { float f; int i; char var; char op; expr_func_t func; } ;
} token_t;

typedef struct _exprnode {
    token_t tok;
    int is_float;
    int history_index;
    int vector_index;
    struct _exprnode *next;
} *exprnode;

struct _mapper_expr {
    exprnode node;
    int vector_size;
    int history_size;
    int history_pos;
    mapper_signal_value_t *input_history;
    mapper_signal_value_t *output_history;
};

typedef enum {
    YEQUAL_Y, YEQUAL_EQ, EXPR, EXPR_RIGHT, TERM, TERM_RIGHT, VALUE, NEGATE,
    VAR_RIGHT, VAR_VECTINDEX, VAR_HISTINDEX, CLOSE_VECTINDEX, CLOSE_HISTINDEX,
    OPEN_PAREN, CLOSE_PAREN, COMMA, END,
} state_t;

typedef struct _stack_obj {
    union { state_t state; exprnode node; };
    enum { ST_STATE, ST_NODE } type;
} stack_obj_t;

=== test.c ===
#include <math.h>
#include <stdio.h>
#include "mapper_expr.h"

int test1() {
    const char str[] = "y=26*2/2+log10(pi)+2.*pow(2,1*(3+7*.1)*1.1+x{-6*2+12})*3*4+cos(2.)";
    mapper_expr e = mapper_expr_new_from_string(str, 1, 1, 1);
    if (!e) { printf("Test FAILED.\n"); return 1; }
    float inp, outp;
    inp = 3.0;
    mapper_expr_evaluate(e, &inp, &outp);
    printf("Evaluate with x=%f: %f (expected: %f)\n", inp, outp,
           26*2/2+log10f(M_PI)+2.f*powf(2,1*(3+7*.1f)*1.1f+inp)*3*4+cosf(2.0f));
    mapper_expr_free(e);
    return 0;
}

int test2() {
    const char str[] = "y=26*2/2+x*30/(20*1)";
    mapper_expr e = mapper_expr_new_from_string(str, 0, 0, 1);
    if (!e) { printf("Test FAILED.\n"); return 1; }
    int inp, outp;
    inp = 3;
    mapper_expr_evaluate(e, &inp, &outp);
    printf("Evaluate with x=%d: %d (expected: %d)\n", inp, outp, 26*2/2+inp*30/(20*1));
    inp = 321;
    mapper_expr_evaluate(e, &inp, &outp);
    printf("Evaluate with x=%d: %d (expected: %d)\n", inp, outp, 26*2/2+inp*30/(20*1));
    mapper_expr_free(e);
    return 0;
}

int main() { int rc=0; rc|=test1(); rc|=test2(); return rc; }

=== Makefile ===
CC := gcc
CFLAGS := -fprofile-arcs -ftest-coverage -g
LDLIBS := -lm -fprofile-arcs -ftest-coverage
all: test
test: test.o mapper_expr.o
	$(CC) $(CFLAGS) -o test test.o mapper_expr.o $(LDLIBS)
%.o: %.c
	$(CC) $(CFLAGS) -c $< -o $@
coverage: test
	./test
	@gcov test.c mapper_expr.c
clean:
	rm -f *.o test *.gcno *.gcda *.gcov

